/**
 * Worked examples, embedded so the command palette can create them.
 *
 * GENERATED FILE — do not edit. Run `python3 Script/build_templates.py` to regenerate it.
 *
 * These are always the pristine generated examples, rebuilt from scratch by the generator rather
 * than read from the `.mdx` files in the workspace. Those files are the user's scratch copies — they
 * get opened and edited while trying the plugin out — and folding those edits into the release
 * would ship whatever the user last tried. The generator is the single source of truth for both.
 *
 * `text` is a complete `.mdx` file: YAML frontmatter plus the explanatory body. It is written
 * verbatim, so the created chart is byte-identical to the example it came from — including the
 * parts of the frontmatter a user would otherwise have to write by hand.
 */

export interface ChartTemplate {
  /** Stable id, used by the tests and by nothing at runtime. */
  id: string;
  /** Shown in the command palette menu. */
  name: string;
  /** One line of guidance under the name. */
  description: string;
  /** Pre-filled filename stem offered in the naming prompt. */
  suggestedName: string;
  /** The whole `.mdx` file, verbatim. */
  text: string;
}

